const input = items[0].json.body || items[0].json;
const text = String(input.text || '').trim();
const pendingField = input.runtime?.pending?.field;
let name = null;
if (pendingField === 'name') {
  name = text || null;
} else {
  const m = text.match(/\b(?:my name is|i am)\s+([A-Za-z][A-Za-z\-]{1,30})\b/i);
  name = m ? m[1] : null;
}
if (!name) {
  const prompt = 'What is your name?';
  return [{ json: {
    trace_id: input.trace_id,
    correlation_id: input.correlation_id || input.trace_id,
    request_id: input.request_id,
    session_id: input.session_id,
    ts_ms: Date.now(),
    status: 'RUNNING',
    result: '',
    client_handler: { command: 'ASK_USER_INPUT', payload: { prompt } },
    client_events: [],
    next_runtime: { active_workflow_id: 'collect_name@1.0.0', pending: { field: 'name', prompt }, context: input.runtime?.context || null, version: input.runtime?.version || 1 },
    errors: []
  }}];
}
return [{ json: {
  trace_id: input.trace_id,
  correlation_id: input.correlation_id || input.trace_id,
  request_id: input.request_id,
  session_id: input.session_id,
  ts_ms: Date.now(),
  status: 'DONE',
  result: '',
  client_handler: { command: 'SHOW_MESSAGE', payload: { message: `Hello, ${name}` } },
  client_events: [],
  next_runtime: { active_workflow_id: null, pending: null, context: input.runtime?.context || null, version: input.runtime?.version || 1 },
  errors: []
}}];
